import{_ as p,a0 as o,w as l,s as r,ao as d,I as n,x as e,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"如何使用 rsync 通過 SSH 恢復部分傳輸的文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 rsync 通過 SSH 恢復部分傳輸的文件 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 rsync 通過 SSH 恢復部分傳輸的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 rsync 通過 SSH 恢復部分傳輸的文件 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180129 How To Resume Partially Transferred Files Over SSH Using Rsync","title":"如何使用 rsync 通過 SSH 恢復部分傳輸的文件","tag":"201805","desc":""},"relativePath":"201805/20180129 How To Resume Partially Transferred Files Over SSH Using Rsync.md","filePath":"[post].md"}'),c={name:"201805/20180129 How To Resume Partially Transferred Files Over SSH Using Rsync.md"};function h(u,s,g,k,b,y){const i=o("Link");return l(),r("div",null,[s[13]||(s[13]=d(`<h1 id="如何使用-rsync-通過-ssh-恢復部分傳輸的文件" tabindex="-1">如何使用 rsync 通過 SSH 恢復部分傳輸的文件 <a class="header-anchor" href="#如何使用-rsync-通過-ssh-恢復部分傳輸的文件" aria-label="Permalink to “如何使用 rsync 通過 SSH 恢復部分傳輸的文件”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/02/Resume-Partially-Transferred-Files-Over-SSH-Using-Rsync.png" alt=""></p><p>由於諸如電源故障、網絡故障或用户干預等各種原因，使用 <code>scp</code> 命令通過 SSH 複製的大型文件可能會中斷、取消或損壞。有一天，我將 Ubuntu 16.04 ISO 文件複製到我的遠程系統。不幸的是斷電了，網絡連接立即斷了。結果麼？複製過程終止！這只是一個簡單的例子。Ubuntu ISO 並不是那麼大，一旦電源恢復，我就可以重新啓動複製過程。但在生產環境中，當你在傳輸大型文件時，你可能並不希望這樣做。</p><p>而且，你不能繼續使用 <code>scp</code> 命令恢復被中止的進度。因為，如果你這樣做，它只會覆蓋現有的文件。這時你會怎麼做？別擔心！這是 <code>rsync</code> 派上用場的地方！<code>rsync</code> 可以幫助你恢復中斷的複製或下載過程。對於那些好奇的人，<code>rsync</code> 是一個快速、多功能的文件複製程序，可用於複製和傳輸遠程和本地系統中的文件或文件夾。</p><p>它提供了大量控制其各種行為的選項，並允許非常靈活地指定要複製的一組文件。它以增量傳輸算法而聞名，它通過僅發送源文件和目標中現有文件之間的差異來減少通過網絡發送的數據量。 <code>rsync</code> 廣泛用於備份和鏡像，以及日常使用中改進的複製命令。</p><p>就像 <code>scp</code> 一樣，<code>rsync</code> 也會通過 SSH 複製文件。如果你想通過 SSH 下載或傳輸大文件和文件夾，我建議您使用 <code>rsync</code>。請注意，應該在兩邊（遠程和本地系統）都安裝 <code>rsync</code> 來恢復部分傳輸的文件。</p><h3 id="使用-rsync-恢復部分傳輸的文件" tabindex="-1">使用 rsync 恢復部分傳輸的文件 <a class="header-anchor" href="#使用-rsync-恢復部分傳輸的文件" aria-label="Permalink to “使用 rsync 恢復部分傳輸的文件”">​</a></h3><p>好吧，讓我給你看一個例子。我將使用命令將 Ubuntu 16.04 ISO 從本地系統複製到遠程系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>這裏，</p><ul><li><code>sk</code>是我的遠程系統的用户名</li><li><code>192.168.43.2</code> 是遠程機器的 IP 地址。</li></ul><p>現在，我按下 <code>CTRL+C</code> 結束它。</p><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk@192.168.43.2&#39;s password: </span></span>
<span class="line"><span>ubuntu-16.04-desktop-amd64.iso 26% 372MB 26.2MB/s 00:39 ETA^c</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/02/scp.png" alt=""></p><p>正如你在上面的輸出中看到的，當它達到 26％ 時，我終止了複製過程。</p><p>如果我重新運行上面的命令，它只會覆蓋現有的文件。換句話説，複製過程不會在我斷開的地方恢復。</p><p>為了恢復複製過程，我們可以使用 <code>rsync</code> 命令，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -P -rsh=ssh Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk@192.168.1.103&#39;s password:</span></span>
<span class="line"><span>sending incremental file list</span></span>
<span class="line"><span>ubuntu-16.04-desktop-amd64.iso</span></span>
<span class="line"><span>                   380.56M 26% 41.05MB/s 0:00:25</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/02/rsync.png" alt=""></p><p>看見了嗎？現在，複製過程在我們之前斷開的地方恢復了。你也可以像下面那樣使用 <code>-partial</code> 而不是 <code>-P</code> 參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync --partial -rsh=ssh Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>這裏，參數 <code>-partial</code> 或 <code>-P</code> 告訴 <code>rsync</code> 命令保留部分下載的文件並恢復進度。</p><p>或者，我們也可以使用以下命令通過 SSH 恢復部分傳輸的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -avP Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -av --partial Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>就是這樣了。你現在知道如何使用 <code>rsync</code> 命令恢復取消、中斷和部分下載的文件。正如你所看到的，它也不是那麼難。如果兩個系統都安裝了 <code>rsync</code>，我們可以輕鬆地通過上面描述的那樣恢復複製的進度。</p><p>如果你覺得本教程有幫助，請在你的社交、專業網絡上分享，並支持我們。還有更多的好東西。敬請關注！</p><p>乾杯!</p><hr>`,33)),n("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.ostechnix.com/how-to-resume-partially-downloaded-or-transferred-files-using-rsync/"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.ostechnix.com/how-to-resume-partially-downloaded-or-transferred-files-using-rsync/",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=e("作者：",-1)),a(i,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[e("SK",-1)])]),_:1}),s[6]||(s[6]=e(" 譯者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:t(()=>[...s[3]||(s[3]=[e("geekpi",-1)])]),_:1}),s[7]||(s[7]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[e("Linux中國",-1)])]),_:1}),s[12]||(s[12]=e(" 榮譽推出",-1))])])}const w=p(c,[["render",h]]);export{S as __pageData,w as default};
